import LAYOUT_DATA from "./motorLayouts.json";

/**
 * Where each `MotorN` output function physically sits on a multicopter frame,
 * per `FRAME_CLASS`/`FRAME_TYPE`. Generated by `npm run build:motor-layouts`
 * from ArduPilot's own motor layout JSON and checked against the official
 * diagrams Frame Setup shows — see that script for the sources.
 *
 * Coordinates are in the motor mixer's own units: `x` positive to the right,
 * `y` positive toward the nose, so a Quad X's Motor1 is at (+0.5, +0.5).
 */
export interface MotorPosition {
    /** The `N` in the `MotorN` servo function. */
    number: number;
    /** `servo` is a MotorN output driving a servo: Tri's yaw tail servo
     * (Motor7), or Single/Coax's four flap servos (Motor1–4). */
    kind: "motor" | "servo";
    /** ArduPilot's own name where it gives one (Single's "front servo"...);
     * otherwise the name is derived from the position. */
    name?: string;
    /** This output carries exactly the same signal as another (Single's
     * Motor6 duplicates Motor5). Drawn as that mark, not a mark of its own. */
    sameAs?: number;
    x: number;
    y: number;
    /** `Either` where the frame has no yaw torque from that motor (Tri, the
     * front pair of a V/A-tail, the no-yaw-torque types). `null` for a servo. */
    spin: "CW" | "CCW" | "Either" | null;
    /** ArduPilot's motor test order (A = 1, B = 2, ...). */
    testOrder: number;
    /** Set only when two motors share a position (coaxial pairs): which one
     * the official diagram draws on top. */
    stack?: "top" | "bottom";
    /** V/A-tail tail rotors only: the rotor is canted, tilted 45° about this
     * axis (SVG space, +y down) — ArduPilot's own `handle_av_tails()` rule. */
    cant?: [number, number];
}

/** A frame line, `[x1, y1, x2, y2]` in the same space as motor positions. */
export type FrameLine = [number, number, number, number];

export interface FrameLayout {
    cls: number;
    type: number;
    /** ArduPilot's own name for the type, as its diagram labels it. */
    typeName: string;
    motors: MotorPosition[];
    /** ArduPilot's explicit frame shape (H rails, V/A-tail booms, Tri, Octa
     * V/H/I). Absent means a spoke from the center to every motor. */
    frameLines?: FrameLine[];
}

/** One mark on a schematic drawing. `rotor` is a helicopter rotor disc,
 * `size` its radius in position units. */
export interface SchematicMark {
    kind: "motor" | "servo" | "rotor";
    x: number;
    y: number;
    spin: "CW" | "CCW" | "Either" | null;
    label?: string;
    size?: number;
    stack?: "top" | "bottom";
}

/**
 * A frame class with no MotorN layout, drawn so Frame Setup can show every
 * class the same way. BiCopter is ArduPilot's own data; the rest are
 * schematic (see Ambiguities below) and never used for output mapping.
 */
export interface FrameSchematic {
    cls: number;
    typeName: string;
    marks: SchematicMark[];
    frameLines?: FrameLine[];
}

interface LayoutFile {
    defaultTypeClasses: number[];
    layouts: FrameLayout[];
    schematics: FrameSchematic[];
}

const DATA = LAYOUT_DATA as LayoutFile;

/**
 * The layout a vehicle with this `FRAME_CLASS`/`FRAME_TYPE` actually flies,
 * or `null` where ArduPilot publishes none (Heli family, SingleCopter,
 * CoaxCopter, BiCopter, the scripted classes, or a type the class doesn't
 * support). Y6 and Tri use their class default for every type they don't
 * name — ArduPilot's own motor test output lists them that way.
 */
export function findFrameLayout(frameClass: number, frameType: number): FrameLayout | null {
    const exact = DATA.layouts.find((l) => l.cls === frameClass && l.type === frameType);
    if (exact) return exact;
    if (DATA.defaultTypeClasses.includes(frameClass)) {
        return DATA.layouts.find((l) => l.cls === frameClass && l.type === 0) ?? null;
    }
    return null;
}

/**
 * What Frame Setup draws for a class/type: the real layout where there is
 * one, else the class's schematic. `frameType` null is the class's own tile,
 * which shows its X layout where it has one (else type 0), the same default
 * the official class images used.
 */
export function findFrameDrawing(frameClass: number, frameType: number | null): FrameLayout | FrameSchematic | null {
    if (frameType === null) {
        return findFrameLayout(frameClass, 1) ?? findFrameLayout(frameClass, 0) ?? DATA.schematics.find((s) => s.cls === frameClass) ?? null;
    }
    return findFrameLayout(frameClass, frameType) ?? DATA.schematics.find((s) => s.cls === frameClass) ?? null;
}

/** Every FRAME_TYPE a class has a layout for, in value order — the choices
 * Frame Setup offers. Y6 and Tri list only the types they name; every other
 * value falls back to their default anyway. */
export function frameTypesFor(frameClass: number): number[] {
    return DATA.layouts.filter((l) => l.cls === frameClass).map((l) => l.type);
}

/** Degrees clockwise from the nose, 0–359. */
export function motorAngle(m: MotorPosition): number {
    return Math.round(((Math.atan2(m.x, m.y) * 180) / Math.PI + 360) % 360);
}

/** 16 points, so Octa X's 22.5° motors get a name of their own instead of
 * colliding with their neighbours under an 8-way split. */
const POSITION_NAMES = [
    "Front", "Front, right side", "Front right", "Right, front side",
    "Right", "Right, rear side", "Rear right", "Rear, right side",
    "Rear", "Rear, left side", "Rear left", "Left, rear side",
    "Left", "Left, front side", "Front left", "Front, left side",
];

/** Plain-words position for a card label. Derived from the coordinates, not
 * published by ArduPilot — see Ambiguities below. */
export function motorPositionName(m: MotorPosition): string {
    if (m.name) return m.name;
    if (m.kind === "servo") return "Tail servo";
    if (Math.hypot(m.x, m.y) < 0.05) return "Center";
    return POSITION_NAMES[Math.round(motorAngle(m) / 22.5) % 16];
}

/*
 * Ambiguities
 * -----------
 * What the sources above don't settle. Taking ArduPilot's motor layout JSON
 * and its official diagrams as the only truth, these are the gaps — each one
 * is handled conservatively rather than filled in with a guess.
 *
 * - SingleCopter and CoaxCopter: in neither the JSON nor the diagrams, so
 *   their layouts come from ArduPilot's source (AP_MotorsSingle/Coax.cpp):
 *   Motor1–4 flap servos, Motor5/6 motors, test order 1–6. Single's source
 *   names the fins front/right/rear/left; Coax's mixer is identical but
 *   uncommented, so its fin positions are carried over from Single — an
 *   inference, not stated. Coax's Motor5 is the CCW motor and Motor6 the CW
 *   one; which is on top isn't stated, so there's no top/bottom for them.
 *   Single's one motor spin isn't stated either (fins handle yaw), and its
 *   Motor6 duplicates Motor5's signal.
 * - Heli, Heli_Dual, HeliQuad: UNVERIFIED — drawn without ArduPilot data
 *   and not yet reviewed by anyone familiar with helicopters; used as-is.
 *   Schematic only — a rotor disc per
 *   rotor, a tail boom for Heli, tandem rotors for Heli_Dual (it also has a
 *   transverse mode the drawing doesn't show).
 * - BiCopter: has an official diagram, but it labels motors L/R, and it runs
 *   on ThrottleLeft/Right and tilt servo functions rather than MotorN. The
 *   mapping from those labels to functions isn't in the data, so no layout.
 * - Heli, Heli_Dual, HeliQuad and the three scripted classes: no layout in
 *   either source (swashplates and scripts, not a fixed motor matrix).
 * - Quad types 6 (Plus reversed), 16 and 17 (no yaw torque): in the JSON but
 *   not listed among `FRAME_TYPE`'s documented values and not diagrammed, so
 *   nothing independent confirms them. Kept, since the JSON comes straight
 *   from the firmware's mixer, but only reachable if a vehicle already has
 *   one of those values set.
 * - Tri type 6 (pitch reversed): in ArduPilot's display JSON, but
 *   `FRAME_TYPE_APPLIES_FOR` in frameDiagrams.ts says Tri ignores
 *   `FRAME_TYPE`. One of the two is wrong; until that's checked against the
 *   firmware, this follows the JSON.
 * - Tri's tail servo: the display JSON has two positions for it (an appended
 *   layout and a class override on opposite sides). The override is what the
 *   official diagram was drawn from, so the build uses it.
 * - Stacked pairs: the JSON gives both motors the same position and says
 *   nothing about which is on top. Only the diagrams do, so frames without a
 *   diagram have no top/bottom information. The official diagrams show a
 *   pair by tilting the whole frame into 3D; ours stay top-down and draw the
 *   pair as two offset marks, which is a presentation choice, not data.
 * - Canted V/A-tail rotors: the official diagrams tilt them 45° in 3D about
 *   an axis through the diagram's center, which also pulls each rotor in to
 *   the end of its tail rod. Ours stay top-down and apply the same tilt as a
 *   2D foreshortening — to the rotor's shape and its position — so they sit
 *   on the rod ends the same way. The axis is checked against the diagrams.
 * - Position names ("Front, right side") and angles are derived here from
 *   the coordinates; ArduPilot publishes no names. V/A-tail and similar
 *   frames use the display JSON's adjusted positions, which are drawing
 *   positions — the geometry of a real airframe may differ.
 * - ArduPlane QuadPlanes use `Q_FRAME_CLASS`/`Q_FRAME_TYPE`; not covered.
 */
